using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    cin >> N >> Q;

    vector<long long> V(N+1), W(N+1);
    for(int i = 1; i <= N; i++) cin >> V[i] >> W[i];

    while(Q--){
        int v;
        long long L;
        cin >> v >> L;

        // Collect items from v to root
        vector<pair<long long,long long>> items; // (weight, value)
        int cur = v;
        while(cur >= 1){
            items.push_back({W[cur], V[cur]});
            cur /= 2;
        }

        int n = items.size();
        int half1 = n / 2;
        int half2 = n - half1;

        // Enumerate all subsets of second half
        vector<pair<long long,long long>> second; // (weight, value)
        for(int mask = 0; mask < (1 << half2); mask++){
            long long tw = 0, tv = 0;
            for(int i = 0; i < half2; i++){
                if(mask >> i & 1){
                    tw += items[half1 + i].first;
                    tv += items[half1 + i].second;
                }
            }
            if(tw <= L) second.push_back({tw, tv});
        }

        // Sort second by weight, then compute prefix max of value
        sort(second.begin(), second.end());
        // Remove dominated: keep only increasing value as weight increases
        vector<pair<long long,long long>> sec2;
        long long maxVal = -1;
        for(auto& p : second){
            if(p.second > maxVal){
                maxVal = p.second;
                sec2.push_back({p.first, p.second});
            }
        }
        // sec2 is sorted by weight with strictly increasing value

        long long ans = 0;
        for(int mask = 0; mask < (1 << half1); mask++){
            long long tw = 0, tv = 0;
            for(int i = 0; i < half1; i++){
                if(mask >> i & 1){
                    tw += items[i].first;
                    tv += items[i].second;
                }
            }
            if(tw > L) continue;
            long long rem = L - tw;
            // Find best in sec2 with weight <= rem
            int lo = 0, hi = (int)sec2.size() - 1, pos = -1;
            while(lo <= hi){
                int mid = (lo + hi) / 2;
                if(sec2[mid].first <= rem){ pos = mid; lo = mid + 1; }
                else hi = mid - 1;
            }
            long long best = tv + (pos >= 0 ? sec2[pos].second : 0);
            ans = max(ans, best);
        }

        cout << ans << "\n";
    }
    return 0;
}

