#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Query {
    int v, L, idx;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> V(N + 1), W(N + 1);
    for (int i = 1; i <= N; ++i) cin >> V[i] >> W[i];

    int Q;
    cin >> Q;
    vector<Query> queries(Q);
    int maxL = 0;
    for (int i = 0; i < Q; ++i) {
        cin >> queries[i].v >> queries[i].L;
        queries[i].idx = i;
        maxL = max(maxL, queries[i].L);
    }

    // Choose a split depth B so that 2^B is manageable.
    // For nodes <= LIM, we precompute knapsack DP for the path root->node.
    int B = 10;
    int LIM = min(N, (1 << B) - 1);

    vector<vector<ll>> dp(LIM + 1, vector<ll>(maxL + 1, 0));
    for (int i = 1; i <= LIM; ++i) {
        if (i > 1) dp[i] = dp[i / 2];
        int wi = W[i], vi = V[i];
        if (wi <= maxL) {
            for (int l = maxL; l >= wi; --l) {
                dp[i][l] = max(dp[i][l], dp[i][l - wi] + vi);
            }
        }
    }

    vector<ll> ans(Q);

    for (auto &qu : queries) {
        int v = qu.v, L = qu.L;

        if (v <= LIM) {
            ans[qu.idx] = dp[v][L];
            continue;
        }

        // Collect items from v up to first ancestor within LIM.
        vector<pair<int,int>> extra; // {weight, value}
        int u = v;
        while (u > LIM) {
            extra.push_back({W[u], V[u]});
            u /= 2;
        }

        ll best = dp[u][L];

        int m = (int)extra.size();
        // Enumerate all subsets of the extra path items.
        for (int mask = 1; mask < (1 << m); ++mask) {
            int sw = 0;
            ll sv = 0;
            for (int j = 0; j < m; ++j) {
                if (mask >> j & 1) {
                    sw += extra[j].first;
                    sv += extra[j].second;
                }
            }
            if (sw <= L) {
                best = max(best, sv + dp[u][L - sw]);
            }
        }

        ans[qu.idx] = best;
    }

    for (int i = 0; i < Q; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

