typedef long long ll;

int cmp_weight(const void *a, const void *b) {
    ll wa = ((ll*)a)[0], wb = ((ll*)b)[0];
    if (wa < wb) return -1;
    if (wa > wb) return 1;
    return 0;
}

int main() {
    int N, Q;
    scanf("%d %d", &N, &Q);

    ll *V = malloc((N+1)*sizeof(ll));
    ll *W = malloc((N+1)*sizeof(ll));

    for (int i = 1; i <= N; i++) {
        scanf("%lld %lld", &V[i], &W[i]);
    }

    for (int q = 0; q < Q; q++) {
        int v;
        ll L;
        scanf("%d %lld", &v, &L);

        // Collect path from v to root
        ll pv[64], pw[64];
        int cnt = 0;
        int cur = v;
        while (cur >= 1) {
            pv[cnt] = V[cur];
            pw[cnt] = W[cur];
            cnt++;
            if (cur == 1) break;
            cur = cur / 2;
        }

        // Meet in the middle
        int half1 = cnt / 2;
        int half2 = cnt - half1;

        int sz2 = 1 << half2;
        ll *w2 = malloc(sz2 * sizeof(ll));
        ll *v2 = malloc(sz2 * sizeof(ll));

        for (int mask = 0; mask < sz2; mask++) {
            w2[mask] = 0; v2[mask] = 0;
            for (int j = 0; j < half2; j++) {
                if (mask & (1 << j)) {
                    w2[mask] += pw[half1 + j];
                    v2[mask] += pv[half1 + j];
                }
            }
        }

        // Sort second half by weight, compute prefix max value
        ll (*pairs2)[2] = malloc(sz2 * sizeof(*pairs2));
        for (int i = 0; i < sz2; i++) { pairs2[i][0] = w2[i]; pairs2[i][1] = v2[i]; }
        qsort(pairs2, sz2, sizeof(*pairs2), cmp_weight);
        for (int i = 1; i < sz2; i++) if (pairs2[i][1] < pairs2[i-1][1]) pairs2[i][1] = pairs2[i-1][1];

        ll ans = 0;
        int sz1 = 1 << half1;
        for (int mask = 0; mask < sz1; mask++) {
            ll tw = 0, tv = 0;
            for (int j = 0; j < half1; j++) if (mask & (1<<j)) { tw += pw[j]; tv += pv[j]; }
            if (tw > L) continue;
            ll rem = L - tw;
            // binary search in pairs2 for largest weight <= rem
            int lo = 0, hi = sz2 - 1, best = -1;
            while (lo <= hi) { int mid=(lo+hi)/2; if(pairs2[mid][0]<=rem){best=mid;lo=mid+1;}else hi=mid-1; }
            ll total = tv + (best >= 0 ? pairs2[best][1] : 0);
            if (total > ans) ans = total;
        }

        printf("%lld\n", ans);
        free(w2); free(v2); free(pairs2);
    }
    free(V); free(W);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define MAXW 100005

typedef struct {
    int v;
    int w;
} Item;

typedef struct Query {
    int v;
    int L;
    int idx;
} Query;

Item items[MAXN];
Query queries[MAXN];
int ans[MAXN];
int dp[MAXW];
int n, q;

// adjacency list for children
int child[MAXN][2];
int child_cnt[MAXN];

// for sorting queries by vertex
int cmp(const void *a, const void *b) {
    Query *qa = (Query*)a;
    Query *qb = (Query*)b;
    return qa->v - qb->v;
}

// store queries per node
typedef struct NodeQuery {
    int L;
    int idx;
} NodeQuery;

NodeQuery node_queries[MAXN];
int query_count[MAXN];
int query_start[MAXN];

void dfs(int u, int maxW) {
    // Save current dp state to restore later
    int old_dp[MAXW];
    memcpy(old_dp, dp, (maxW+1)*sizeof(int));

    // Add current item (unbounded knapsack style update)
    int v = items[u].v;
    int w = items[u].w;
    for (int j = w; j <= maxW; j++) {
        if (dp[j-w] + v > dp[j])
            dp[j] = dp[j-w] + v;
    }

    // Answer queries for this node
    for (int i = 0; i < query_count[u]; i++) {
        int L = node_queries[query_start[u] + i].L;
        int idx = node_queries[query_start[u] + i].idx;
        int best = 0;
        for (int j = 0; j <= L && j <= maxW; j++) {
            if (dp[j] > best) best = dp[j];
        }
        ans[idx] = best;
    }

    // Recurse to children
    for (int i = 0; i < child_cnt[u]; i++) {
        dfs(child[u][i], maxW);
    }

    // Restore dp
    memcpy(dp, old_dp, (maxW+1)*sizeof(int));
}

int main() {
    scanf("%d %d", &n, &q);

    int maxW = 0;
    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &items[i].v, &items[i].w);
        if (items[i].w > maxW) maxW = items[i].w;
    }

    // Build tree
    for (int i = 2; i <= n; i++) {
        int parent = i / 2;
        child[parent][child_cnt[parent]++] = i;
    }

    // Read queries
    int maxL = 0;
    for (int i = 0; i < q; i++) {
        scanf("%d %d", &queries[i].v, &queries[i].L);
        queries[i].idx = i;
        if (queries[i].L > maxL) maxL = queries[i].L;
    }

    // Group queries by vertex
    qsort(queries, q, sizeof(Query), cmp);
    int cur_v = 0;
    int pos = 0;
    for (int i = 0; i < q; i++) {
        if (queries[i].v != cur_v) {
            cur_v = queries[i].v;
            query_start[cur_v] = pos;
            query_count[cur_v] = 0;
        }
        node_queries[pos].L = queries[i].L;
        node_queries[pos].idx = queries[i].idx;
        query_count[cur_v]++;
        pos++;
    }

    int limit = maxL;
    if (maxW > limit) limit = maxW;

    // Initialize dp
    memset(dp, -1, (limit+1)*sizeof(int));
    dp[0] = 0;

    dfs(1, limit);

    for (int i = 0; i < q; i++) {
        printf("%d\n", ans[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 262144
#define HALF 512

typedef long long ll;

typedef struct {
    int w;
    ll v;
} Pair;

static int N;
static ll V[MAXN + 5];
static int Wt[MAXN + 5];

static Pair *dp[HALF + 5];
static int dpsz[HALF + 5];

static int cmpPair(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->w != y->w) return x->w - y->w;
    if (x->v < y->v) return -1;
    if (x->v > y->v) return 1;
    return 0;
}

static void build_small() {
    dp[0] = (Pair *)malloc(sizeof(Pair));
    dp[0][0].w = 0;
    dp[0][0].v = 0;
    dpsz[0] = 1;

    for (int i = 1; i <= HALF && i <= N; i++) {
        int p = i / 2;
        int ps = dpsz[p];
        Pair *tmp = (Pair *)malloc(sizeof(Pair) * (ps * 2));
        int idx = 0;
        for (int j = 0; j < ps; j++) {
            tmp[idx++] = dp[p][j];
            tmp[idx].w = dp[p][j].w + Wt[i];
            tmp[idx].v = dp[p][j].v + V[i];
            idx++;
        }

        qsort(tmp, idx, sizeof(Pair), cmpPair);

        Pair *res = (Pair *)malloc(sizeof(Pair) * idx);
        int rs = 0;
        ll best = -1;
        for (int j = 0; j < idx; j++) {
            if (tmp[j].v > best) {
                res[rs++] = tmp[j];
                best = tmp[j].v;
            }
        }
        free(tmp);
        dp[i] = res;
        dpsz[i] = rs;
    }
}

static ll query_small(int v, int L) {
    Pair *arr = dp[v];
    int sz = dpsz[v];
    int lo = 0, hi = sz - 1, ans = 0;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (arr[mid].w <= L) {
            ans = mid;
            lo = mid + 1;
        } else hi = mid - 1;
    }
    if (arr[ans].w <= L) return arr[ans].v;
    return 0;
}

int main() {
    if (scanf("%d", &N) != 1) return 0;
    for (int i = 1; i <= N; i++) {
        scanf("%lld %d", &V[i], &Wt[i]);
    }

    build_small();

    int Q;
    scanf("%d", &Q);

    while (Q--) {
        int v, L;
        scanf("%d %d", &v, &L);

        int extra_nodes[32];
        int extra_cnt = 0;

        while (v > HALF) {
            extra_nodes[extra_cnt++] = v;
            v >>= 1;
        }

        ll ans = 0;
        int subsets = 1 << extra_cnt;
        for (int mask = 0; mask < subsets; mask++) {
            int sw = 0;
            ll sv = 0;
            for (int i = 0; i < extra_cnt; i++) {
                if (mask & (1 << i)) {
                    sw += Wt[extra_nodes[i]];
                    sv += V[extra_nodes[i]];
                }
            }
            if (sw > L) continue;

            Pair *arr = dp[v];
            int sz = dpsz[v];
            int rem = L - sw;

            int lo = 0, hi = sz - 1, besti = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                if (arr[mid].w <= rem) {
                    besti = mid;
                    lo = mid + 1;
                } else hi = mid - 1;
            }

            ll cur = sv + (besti >= 0 ? arr[besti].v : 0);
            if (cur > ans) ans = cur;
        }

        printf("%lld\n", ans);
    }

    return 0;
}

