public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        long[] V = new long[N + 1];
        long[] W = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            V[i] = Long.parseLong(st.nextToken());
            W[i] = Long.parseLong(st.nextToken());
        }
        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int v = Integer.parseInt(st.nextToken());
            long L = Long.parseLong(st.nextToken());
            // Collect path from v to root
            List<Integer> path = new ArrayList<>();
            int cur = v;
            while (cur >= 1) {
                path.add(cur);
                cur /= 2;
            }
            int n = path.size();
            // Meet in the middle
            int half1 = n / 2;
            int half2 = n - half1;
            // First half: indices 0..half1-1
            // Second half: indices half1..n-1
            long[] ws2 = new long[1 << half2];
            long[] vs2 = new long[1 << half2];
            for (int mask = 0; mask < (1 << half2); mask++) {
                long tw = 0, tv = 0;
                for (int j = 0; j < half2; j++) {
                    if ((mask >> j & 1) == 1) {
                        int idx = path.get(half1 + j);
                        tw += W[idx]; tv += V[idx];
                    }
                }
                ws2[mask] = tw; vs2[mask] = tv;
            }
            // Sort second half by weight, build Pareto front
            Integer[] order = new Integer[1 << half2];
            for (int i = 0; i < order.length; i++) order[i] = i;
            Arrays.sort(order, (a, b) -> Long.compare(ws2[a], ws2[b]));
            long[] sw = new long[1 << half2], sv = new long[1 << half2];
            int sz = 0;
            long maxVal = -1;
            for (int i = 0; i < order.length; i++) {
                if (ws2[order[i]] > L) break;
                if (vs2[order[i]] > maxVal) { maxVal = vs2[order[i]]; sw[sz] = ws2[order[i]]; sv[sz] = maxVal; sz++; }
            }
            long ans = 0;
            for (int mask = 0; mask < (1 << half1); mask++) {
                long tw = 0, tv = 0;
                for (int j = 0; j < half1; j++) {
                    if ((mask >> j & 1) == 1) { int idx = path.get(j); tw += W[idx]; tv += V[idx]; }
                }
                if (tw > L) continue;
                long rem = L - tw;
                int lo = 0, hi = sz - 1, best = -1;
                while (lo <= hi) { int mid = (lo + hi) / 2; if (sw[mid] <= rem) { best = mid; lo = mid + 1; } else hi = mid - 1; }
                ans = Math.max(ans, tv + (best >= 0 ? sv[best] : 0));
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/*
 * Meet-in-the-middle on the path from root to a queried node.
 *
 * Tree:
 *   parent(i) = i/2
 * Query:
 *   among items on path root..v, choose subset with total weight <= L maximizing total value.
 *
 * Key observation:
 *   Depth of node i is at most floor(log2 i) + 1, so for N <= typical constraints this path is short.
 *
 * We split the path into:
 *   - upper fixed part: first B levels from root
 *   - lower variable part: remaining nodes down to v
 *
 * Precompute for every node x among the first (2^B - 1) nodes:
 *   all subset (weight, value) pairs on the path root..x,
 *   compressed so for increasing weight we keep only strictly improving values.
 *
 * For a query(v, L):
 *   - climb from v upward until entering the precomputed region, collecting the lower part items
 *   - enumerate all subsets of the lower part
 *   - for each subset with weight w and value val, binary search in precomputed list of the upper node
 *     for max value with weight <= L-w
 *
 * Complexity:
 *   Precompute: sum over small nodes of O(2^depth), tiny for B=10.
 *   Query: O(2^k log M), where k is number of non-precomputed path nodes (<= about 8 if N <= 2e5).
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Pair {
        long w, v;
        Pair(long w, long v) {
            this.w = w;
            this.v = v;
        }
    }

    static int N;
    static long[] V, W;

    static final int B = 10; // precompute first 2^B - 1 nodes
    static int LIMIT_NODE;
    static long[][] preW;
    static long[][] preV;

    static void buildPrecompute() {
        LIMIT_NODE = Math.min(N, (1 << B) - 1);
        preW = new long[LIMIT_NODE + 1][];
        preV = new long[LIMIT_NODE + 1][];

        preW[0] = new long[]{0};
        preV[0] = new long[]{0};

        for (int x = 1; x <= LIMIT_NODE; x++) {
            int p = x / 2;
            long[] pw = preW[p];
            long[] pv = preV[p];
            int m = pw.length;
            Pair[] arr = new Pair[m * 2];
            for (int i = 0; i < m; i++) {
                arr[i] = new Pair(pw[i], pv[i]);
                arr[i + m] = new Pair(pw[i] + W[x], pv[i] + V[x]);
            }
            Arrays.sort(arr, (a, b) -> {
                if (a.w != b.w) return Long.compare(a.w, b.w);
                return Long.compare(b.v, a.v);
            });

            ArrayList<Long> ws = new ArrayList<>();
            ArrayList<Long> vs = new ArrayList<>();
            long best = -1;
            int i = 0;
            while (i < arr.length) {
                long weight = arr[i].w;
                long maxValAtWeight = arr[i].v;
                i++;
                while (i < arr.length && arr[i].w == weight) {
                    if (arr[i].v > maxValAtWeight) maxValAtWeight = arr[i].v;
                    i++;
                }
                if (maxValAtWeight > best) {
                    best = maxValAtWeight;
                    ws.add(weight);
                    vs.add(best);
                }
            }

            preW[x] = new long[ws.size()];
            preV[x] = new long[vs.size()];
            for (int j = 0; j < ws.size(); j++) {
                preW[x][j] = ws.get(j);
                preV[x][j] = vs.get(j);
            }
        }
    }

    static long query(int v, long L) {
        int[] nodes = new int[64];
        int cnt = 0;
        int cur = v;
        while (cur > LIMIT_NODE) {
            nodes[cnt++] = cur;
            cur >>= 1;
        }

        long ans = 0;
        int total = 1 << cnt;
        for (int mask = 0; mask < total; mask++) {
            long sw = 0, sv = 0;
            for (int i = 0; i < cnt; i++) {
                if (((mask >> i) & 1) != 0) {
                    sw += W[nodes[i]];
                    if (sw > L) break;
                    sv += V[nodes[i]];
                }
            }
            if (sw > L) continue;

            long rem = L - sw;
            long bestUpper = bestValue(cur, rem);
            ans = Math.max(ans, sv + bestUpper);
        }
        return ans;
    }

    static long bestValue(int node, long limit) {
        long[] ws = preW[node];
        long[] vs = preV[node];
        int l = 0, r = ws.length - 1, res = -1;
        while (l <= r) {
            int mid = (l + r) >>> 1;
            if (ws[mid] <= limit) {
                res = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return res == -1 ? 0 : vs[res];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        N = fs.nextInt();
        V = new long[N + 1];
        W = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            V[i] = fs.nextInt();
            W[i] = fs.nextInt();
        }

        buildPrecompute();

        int Q = fs.nextInt();
        for (int i = 0; i < Q; i++) {
            int v = fs.nextInt();
            long L = fs.nextInt();
            out.append(query(v, L)).append('\n');
        }

        System.out.print(out.toString());
    }
